  function persist() { const snapshot=packState(state);const serialized=JSON.stringify(snapshot);if(new TextEncoder().encode(serialized).length>13000){storageWarning('本次演示修改尚未保存：内容超过预览存储容量，刷新可能丢失。');return;}lastSentSnapshot=serialized;sentSnapshots.add(serialized);if(sentSnapshots.size>40)sentSnapshots.delete(sentSnapshots.values().next().value); if(typeof window.openai?.setWidgetState==='function') window.openai.setWidgetState({modelContent:{prototype:'工作号每日质检',channel:state.channel,date:state.date,tab:state.tab,configVersion:state.config.version,promptVersions:Object.fromEntries(Object.entries(state.templates).map(([k,v])=>[k,v.version])),page:state.page,metrics:state.config.metrics.filter(m=>m.enabled).map(m=>m.name),reviewed:Object.keys(state.reviews).length},privateContent:{schema:'quality-daily-v2',state:snapshot}}).catch(()=>{storageWarning('演示保存失败：修改仅在当前页面生效，刷新会丢失。');render();}); }
  window.addEventListener('openai:set_globals', e=>{ const saved=e.detail?.globals?.widgetState?.privateContent;if(['quality-daily-v1','quality-daily-v2'].includes(saved?.schema)&&!sentSnapshots.has(JSON.stringify(saved.state))){restore(saved);render();} });
  const channelNameFor=channel=>channel==='wecom'?'企微':'个微';
