  function button(label, action, data={}, cls='', disabled=false) {return `<button type="button" class="q-button cursor-interaction ${cls}" data-action="${action}" ${disabled?'disabled':''} ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${label}</button>`;}
