    const deps=M.dependencies(m.base||m.id),missing=deps.map(id=>c.dimensions.find(d=>d.id===id)).filter(d=>d&&d.enabled===false);
    if(missing.length)return {label:'未评估',reason:'对应检查已停用：'+missing.map(d=>d.name).join('、')+'。历史结果可从报告原口径查看。'};if(['risk_count','high_issue_count','medium_risk'].includes(m.base||m.id)&&c.dimensions.some(d=>d.kind==='judgement'&&!d.enabled))return {label:'未评估',reason:'检查范围已变化，当前配置未完成完整风险评估；可查看报告原口径。'};if(!preview)return null;
    const semantic=!['conv_count','message_count','timeout_count','timeout_rate','timeout_events','deep_count','response_avg','response_max'].includes(m.base||m.id);
    if(semantic&&((deps.some(id=>c.dimensions.some(d=>d.id===id&&d.enabled&&d.newField))||(['risk_count','high_issue_count','medium_risk'].includes(m.base||m.id)&&c.dimensions.some(d=>d.enabled&&d.newField)))||state.templates[state.channel].text!==baselineTemplates[state.channel].text||state.templates[state.channel].modelBinding!==baselineTemplates[state.channel].modelBinding))return {label:'待生成',reason:'分析规则或提示词已变化，需要新分析事实。下方原文仍为历史记录。'};
    return null;
