  function productAnalysisStatus(){if(state.view!=='preview')return null;const d=cfg().dimensions.find(d=>d.id==='product');if(d?.enabled===false)return '产品触达维度未启用，当前预览未评估。';if(d?.newField||activeTemplate().text!==baselineTemplates[state.channel].text||activeTemplate().modelBinding!==baselineTemplates[state.channel].modelBinding)return '产品分析规则或提示词已变化，需要生成新分析事实。';return null;}
